@page "/book-appointment"
@rendermode InteractiveServer
@using sv_1caba1f65d4543aab96916dffbdcab46.Models
@using sv_1caba1f65d4543aab96916dffbdcab46.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book an Appointment</h3>

@* ───── STEP 1: Patient Information ───── *@
<div class="card mb-4">
    <div class="card-header"><strong>Step 1:</strong> Patient Information</div>
    <div class="card-body">
        <EditForm EditContext="step1Context" OnValidSubmit="HandleStep1Valid" FormName="step1">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label class="form-label">Patient Name</label>
                <InputText class="form-control" @bind-Value="patientInfo.Name" />
                <ValidationMessage For="() => patientInfo.Name" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <InputText class="form-control" @bind-Value="patientInfo.Email" />
                <ValidationMessage For="() => patientInfo.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label">Phone</label>
                <InputText class="form-control" @bind-Value="patientInfo.Phone" />
                <ValidationMessage For="() => patientInfo.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label">Insurance Provider</label>
                <InputSelect class="form-select" @bind-Value="patientInfo.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => patientInfo.InsuranceProvider" />
            </div>

            <button type="submit" class="btn btn-primary">Next &rarr;</button>
        </EditForm>
    </div>
</div>

@* ───── STEP 2: Appointment Details ───── *@
@if (showStep2)
{
    <div class="card mb-4">
        <div class="card-header"><strong>Step 2:</strong> Appointment Details</div>
        <div class="card-body">
            <EditForm EditContext="step2Context" OnSubmit="HandleStep2Submit" FormName="step2">
                <DataAnnotationsValidator />
                <CustomValidator @ref="step2Validator" />

                <div class="mb-3">
                    <label class="form-label">Preferred Doctor</label>
                    <InputSelect class="form-select" @bind-Value="appointmentDetails.Doctor"
                                 @bind-Value:after="OnDoctorOrDateChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => appointmentDetails.Doctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Date</label>
                    <InputDate class="form-control" @bind-Value="appointmentDetails.Date"
                               @bind-Value:after="OnDoctorOrDateChanged" />
                    <ValidationMessage For="() => appointmentDetails.Date" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Time Slot</label>
                    <InputSelect class="form-select" @bind-Value="appointmentDetails.TimeSlot"
                                 disabled="@(!availableSlots.Any())">
                        <option value="">-- Select --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => appointmentDetails.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Reason for Visit</label>
                    <InputTextArea class="form-control" rows="3"
                                   @bind-Value="appointmentDetails.ReasonForVisit" />
                    <ValidationMessage For="() => appointmentDetails.ReasonForVisit" />
                </div>

                <button type="submit" class="btn btn-success" disabled="@isSubmitting">
                    @(isSubmitting ? "Checking…" : "Check Availability")
                </button>
            </EditForm>
        </div>
    </div>
}

@if (confirmationMessage is not null)
{
    <div class="alert alert-success">@confirmationMessage</div>
}

@code {
    private PatientInfoModel patientInfo = new();
    private AppointmentDetailsModel appointmentDetails = new();

    private EditContext step1Context = default!;
    private EditContext step2Context = default!;
    private CustomValidator? step2Validator;

    private bool showStep2;
    private bool isSubmitting;
    private string? confirmationMessage;

    private List<string> doctors = [];
    private List<string> availableSlots = [];

    protected override async Task OnInitializedAsync()
    {
        step1Context = new EditContext(patientInfo);
        step2Context = new EditContext(appointmentDetails);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void HandleStep1Valid()
    {
        showStep2 = true;
    }

    private async Task OnDoctorOrDateChanged()
    {
        appointmentDetails.TimeSlot = null;
        if (!string.IsNullOrEmpty(appointmentDetails.Doctor) && appointmentDetails.Date.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(
                appointmentDetails.Doctor, appointmentDetails.Date.Value);
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task HandleStep2Submit()
    {
        step2Validator!.ClearErrors();
        confirmationMessage = null;

        if (!step2Context.Validate())
            return;

        // Custom date-in-future validation
        if (appointmentDetails.Date.HasValue
            && appointmentDetails.Date.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            step2Validator.DisplayErrors(new Dictionary<string, List<string>>
            {
                [nameof(AppointmentDetailsModel.Date)] = ["Date must be in the future."]
            });
            return;
        }

        isSubmitting = true;
        try
        {
            var serverErrors = await AppointmentSvc.ValidatePatientAsync(
                patientInfo.Email,
                patientInfo.InsuranceProvider,
                appointmentDetails.Doctor,
                appointmentDetails.TimeSlot);

            if (serverErrors.Count > 0)
            {
                // Map service field names to model property names
                var mapped = new Dictionary<string, List<string>>();
                foreach (var (key, msgs) in serverErrors)
                {
                    var propName = key switch
                    {
                        "email" => nameof(PatientInfoModel.Email),
                        "doctor" => nameof(AppointmentDetailsModel.Doctor),
                        "timeSlot" => nameof(AppointmentDetailsModel.TimeSlot),
                        _ => key
                    };
                    mapped[propName] = msgs;
                }
                step2Validator.DisplayErrors(mapped);
                return;
            }

            confirmationMessage =
                $"Appointment booked with {appointmentDetails.Doctor} on " +
                $"{appointmentDetails.Date:MMM dd, yyyy} at {appointmentDetails.TimeSlot}.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

